 * "License"); you may not use this file except in compliance with the
 * License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <stdbool.h>

/* dm_voice.h 定义 voice_decision_t / voice_category_t / voice_action_t */
#include "dm_voice.h"

/* dm_tone_play 定义在 luncher_dm（deskmate_ui.c），跨 app 符号共享 */
extern void dm_tone_play(const char *name);
extern void dm_tone_play_seq(const char *intro, const char *voice);

typedef struct
{
  int         scene;
  const char *label;
} scene_info_t;

static const scene_info_t g_scenes[] =
{
  {  1, "开机首次 (greet_first)" },
  {  2, "当天首次 (greet_hello)" },
  {  3, "普通回来" },
  {  4, "短离开回来" },
  {  5, "长离开回来" },
  {  6, "久坐后回来" },
  {  7, "多次趋静" },
  {  8, "晚上回来" },
  {  9, "深夜回来" },
  { 10, "AI交互中" },
  { 11, "音乐播放中" },
  { 12, "拒后回来" },
};

#define SCENE_COUNT (sizeof(g_scenes) / sizeof(g_scenes[0]))

static const char *action_str(int a)
{
  switch (a)
  {
  case 0:  return "NONE(静默)";
  case 1:  return "UI_ONLY(只卡片)";
  case 2:  return "PARTICLE(粒子)";
  case 3:  return "SHORT(短句)";
  case 4:  return "FULL(完整句)";
  default: return "???";
  }
}

static const char *cat_str(int c)
{
  switch (c)
  {
  case 0:  return "GREETING";
  case 1:  return "HEALTH_REMINDER";
  case 2:  return "TEASING";
  case 3:  return "CARING";
  case 4:  return "SYSTEM_RESPONSE";
  default: return "???";
  }
}

static const char *period_str(int hour)
{
  if (hour < 0)  return "未对时";
  if (hour < 5)  return "深夜";
  if (hour < 10) return "早晨";
  if (hour < 11) return "上午";
  if (hour < 14) return "中午";
  if (hour < 18) return "下午";
  if (hour < 23) return "晚上";
  return "深夜";
}

static void run_one(int scene, int hour, bool do_play)
{
  voice_decision_t d;

  d = voice_director_test_scene(scene, hour, -1, -1, false, 0);

  printf("[voice_sim] scene=%d hour=%d(%s) → action=%s cat=%s wav=%s\n",
         scene, hour, period_str(hour),
         action_str(d.action), cat_str(d.category),
         d.wav ? d.wav : "(null)");

  if (do_play && d.wav)
    {
      printf("[voice_sim] playing: %s\n", d.wav);
      dm_tone_play(d.wav);
    }
}

int main(int argc, char *argv[])
{
  int hour = -1;
  bool do_play = false;
  bool do_all = false;
  int scene = 0;
  int i;

  if (argc < 2)
    {
      printf("usage: voice_sim <scene|all> [hour] [play]\n");
      printf("  scene 1~12 (1=开机首次 2=当天首次 3=普通 4=短离开\n");
      printf("    5=长离开 6=久坐 7=趋静 8=晚上 9=深夜 10=AI 11=音乐 12=拒后)\n");
      printf("  hour 0~23 (default: scene default)\n");
      printf("  play  - also play the wav\n");
      printf("  all   - run all 12 scenes\n");
      printf("examples:\n");
      printf("  voice_sim 1           - 开机首次，默认时段\n");
      printf("  voice_sim 3 15        - 普通回来，下午3点\n");
      printf("  voice_sim 8 20 play   - 晚上回来，播放\n");
      printf("  voice_sim all         - 全场景遍历\n");
      return 1;
    }

  if (strcmp(argv[1], "all") == 0)
    do_all = true;
  else
    scene = atoi(argv[1]);

  for (i = 2; i < argc; i++)
    {
      if (strcmp(argv[i], "play") == 0)
        do_play = true;
      else
        hour = atoi(argv[i]);
    }

  if (do_all)
    {
      printf("[voice_sim] === 全场景遍历 hour=%d ===\n",
             hour >= 0 ? hour : -1);
      for (i = 0; i < (int)SCENE_COUNT; i++)
        {
          run_one(g_scenes[i].scene, hour, do_play);
          if (i + 1 < (int)SCENE_COUNT)
            sleep(do_play ? 6 : 1);
        }
      printf("[voice_sim] === done (%d scenes) ===\n", (int)SCENE_COUNT);
      return 0;
    }

  if (scene < 1 || scene > 12)
    {
      printf("voice_sim: scene must be 1~12 (got %d)\n", scene);
      return 1;
    }

  run_one(scene, hour, do_play);
  return 0;
}

