/****************************************************************************
 * apps/vendor/allwinnertech/apps/luncher_dm/dm_pet.c
 * 电子宠物模块 — 锁屏精灵动画 + 健康事件联动
 *
 * 架构：
 *   状态机（6 态）← dm_health 事件驱动
 *   精灵动画（lv_image + lv_timer_t 帧切换）
 *   持久化（/data/pet_state.json，定时保存）
 *   占位精灵：LVGL 内置符号+颜色矩形（后续替换为 PNG sprite）
 *
 * 集成点：ui_home.c show_standby() 里加一行 dm_pet_create(overlay)
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.  The
 * ASF licenses this file to you under the Apache License, Version 2.0 (the
 * "License"); you may not use this file except in compliance with the
 * License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#include <lvgl/lvgl.h>
#include "dm_pet.h"
#include "deskmate_ui.h"   /* DM(), COL_*, FONT_* */

/****************************************************************************
 * 配置常量
 ****************************************************************************/

#define PET_SAVE_PATH       "/data/pet_state.json"
#define PET_SAVE_INTERVAL_S 60      /* 每 60 秒自动保存 */
#define PET_SIZE             DM(120) /* 宠物精灵尺寸 120x120 */
#define PET_MARGIN           DM(20)  /* 距屏幕边缘 */
#define PET_IDLE_TIMEOUT_S   300     /* 5 分钟无互动 → sleeping */
#define PET_FRAME_MS         500     /* 动画帧间隔 500ms */
#define PET_MOOD_DECAY_RATE  1       /* 每分钟心情衰减 */
#define PET_MOOD_MIN         10      /* 心情最低值 */

/****************************************************************************
 * 占位精灵（后续替换为 PNG → lv_image_dsc_t）
 *
 * 当前用 LVGL canvas 绘制简单图形：圆形身体 + 眼睛 + 嘴巴
 * 后续替换流程：
 *   1. 用 AI 生成 PNG sprite（120x120，各状态 4~8 帧）
 *   2. LVGL Image Converter 转为 C 数组（RGB565A8 格式）
 *   3. 替换 g_pet_frames 数组
 ****************************************************************************/

/* 每个状态的颜色（占位用，后续换 PNG） */
static const lv_color_t g_state_colors[PET_STATE_COUNT] =
{
    [PET_STATE_IDLE]     = {{0x4C, 0xAF, 0x50}},  /* 绿色 */
    [PET_STATE_HAPPY]    = {{0xFF, 0xC1, 0x07}},  /* 金色 */
    [PET_STATE_SAD]      = {{0x90, 0xA4, 0xAE}},  /* 灰蓝 */
    [PET_STATE_SLEEPING] = {{0x7E, 0x57, 0xC2}},  /* 紫色 */
    [PET_STATE_REMIND]   = {{0xFF, 0x98, 0x00}},  /* 橙色 */
    [PET_STATE_CELEBRATE]= {{0xE9, 0x1E, 0x63}},  /* 粉红 */
};

/* 每个状态的表情符号（占位用） */
static const char *g_state_symbols[PET_STATE_COUNT] =
{
    [PET_STATE_IDLE]     = LV_SYMBOL_EYE_OPEN,
    [PET_STATE_HAPPY]    = LV_SYMBOL_OK,
    [PET_STATE_SAD]      = LV_SYMBOL_CLOSE,
    [PET_STATE_SLEEPING] = LV_SYMBOL_WIFI,   /* zzz 占位 */
    [PET_STATE_REMIND]   = LV_SYMBOL_BELL,
    [PET_STATE_CELEBRATE]= LV_SYMBOL_TROPHY,
};

/* 每个状态的动画帧偏移量（用于周期性摆动效果） */
static const int g_idle_offsets[] = {0, -3, 0, 3, 0};

/****************************************************************************
 * 内部状态
 ****************************************************************************/

static lv_obj_t    *g_pet_cont;          /* 宠物容器 */
static lv_obj_t    *g_pet_body;          /* 身体（圆形） */
static lv_obj_t    *g_pet_symbol;        /* 表情符号 */
static lv_obj_t    *g_pet_bubble;        /* 气泡文字 */
static lv_obj_t    *g_pet_bubble_lbl;    /* 气泡标签 */
static lv_timer_t  *g_pet_anim_timer;    /* 动画帧 timer */
static lv_timer_t  *g_pet_save_timer;    /* 自动保存 timer */
static lv_timer_t  *g_pet_idle_timer;    /* 空闲检测 timer */

static dm_pet_state_t g_state      = PET_STATE_IDLE;
static dm_pet_data_t  g_pet_data;
static int            g_frame_idx  = 0;
static int            g_bubble_cnt = 0;   /* 气泡剩余显示帧数 */

/****************************************************************************
 * JSON 简易解析/序列化（不依赖 cJSON，自写最小实现）
 ****************************************************************************/

static void pet_save(void)
{
    FILE *f = fopen(PET_SAVE_PATH, "w");
    if (!f) return;
    fprintf(f,
        "{\"mood\":%d,\"energy\":%d,\"growth\":%d,"
        "\"total_water\":%d,\"total_stands\":%d,"
        "\"days_alive\":%d,\"last_interaction\":%ld}\n",
        g_pet_data.mood, g_pet_data.energy, g_pet_data.growth,
        g_pet_data.total_water, g_pet_data.total_stands,
        g_pet_data.days_alive, g_pet_data.last_interaction);
    fclose(f);
}

static void pet_load(void)
{
    FILE *f = fopen(PET_SAVE_PATH, "r");
    if (!f)
    {
        /* 首次运行：初始化默认值 */
        g_pet_data.mood             = 80;
        g_pet_data.energy           = 100;
        g_pet_data.growth           = 0;
        g_pet_data.total_water      = 0;
        g_pet_data.total_stands     = 0;
        g_pet_data.days_alive       = 0;
        g_pet_data.last_interaction = time(NULL);
        return;
    }
    /* 简单 fscanf 解析（格式由 pet_save 保证） */
    fscanf(f,
        "{\"mood\":%d,\"energy\":%d,\"growth\":%d,"
        "\"total_water\":%d,\"total_stands\":%d,"
        "\"days_alive\":%d,\"last_interaction\":%ld",
        &g_pet_data.mood, &g_pet_data.energy, &g_pet_data.growth,
        &g_pet_data.total_water, &g_pet_data.total_stands,
        &g_pet_data.days_alive, &g_pet_data.last_interaction);
    fclose(f);
    LV_LOG_USER("[pet] loaded: mood=%d growth=%d water=%d",
                g_pet_data.mood, g_pet_data.growth, g_pet_data.total_water);
}

/****************************************************************************
 * 气泡文字（宠物说话）
 ****************************************************************************/

static const char *g_bubble_reactions[PET_EVT_COUNT] =
{
    [PET_EVT_WATER_DRANK]  = "好喝！再来一杯~",
    [PET_EVT_STOOD_UP]     = "终于动了！",
    [PET_EVT_LONG_SIT]     = "腰要断了……",
    [PET_EVT_GOAL_REACHED] = "今天你最强！",
    [PET_EVT_REMIND]       = "该喝水啦！",
    [PET_EVT_TOUCH]        = "嘿嘿~",
    [PET_EVT_IDLE_LONG]    = "zzZ...",
    [PET_EVT_WAKE_UP]      = "回来啦！",
};

static void pet_show_bubble(const char *text)
{
    if (!g_pet_bubble || !g_pet_bubble_lbl || !text)
        return;
    lv_label_set_text(g_pet_bubble_lbl, text);
    lv_obj_clear_flag(g_pet_bubble, LV_OBJ_FLAG_HIDDEN);
    g_bubble_cnt = 6;  /* 6 帧 ≈ 3 秒后自动隐藏 */
}

static void pet_hide_bubble(void)
{
    if (g_pet_bubble)
        lv_obj_add_flag(g_pet_bubble, LV_OBJ_FLAG_HIDDEN);
    g_bubble_cnt = 0;
}

/****************************************************************************
 * 状态切换 + 精灵更新
 ****************************************************************************/

static void pet_set_state(dm_pet_state_t new_state)
{
    if (g_state == new_state)
        return;

    dm_pet_state_t old = g_state;
    g_state = new_state;
    g_frame_idx = 0;

    /* 更新颜色 */
    if (g_pet_body)
        lv_obj_set_style_bg_color(g_pet_body,
                                  g_state_colors[new_state], 0);

    /* 更新表情符号 */
    if (g_pet_symbol)
        lv_label_set_text(g_pet_symbol, g_state_symbols[new_state]);

    LV_LOG_USER("[pet] state: %d → %d", old, new_state);
    (void)old;
}

/****************************************************************************
 * 动画帧 timer（每 PET_FRAME_MS 调用一次）
 ****************************************************************************/

static void pet_anim_cb(lv_timer_t *t)
{
    (void)t;
    g_frame_idx++;

    /* 占位动画：idle/happy 状态下微小上下浮动 */
    if (g_state == PET_STATE_IDLE || g_state == PET_STATE_HAPPY)
    {
        int off = g_idle_offsets[g_frame_idx %
                                (sizeof(g_idle_offsets) /
                                 sizeof(g_idle_offsets[0]))];
        if (g_pet_cont)
            lv_obj_set_y(g_pet_cont,
                         lv_obj_get_y(g_pet_cont) + off);
    }

    /* sleeping 状态：缓慢呼吸效果（透明度周期） */
    if (g_state == PET_STATE_SLEEPING && g_pet_body)
    {
        lv_opa_t opa = (lv_opa_t)(155 + 100 *
                        ((g_frame_idx % 4 < 2) ? 1 : -1));
        lv_obj_set_style_bg_opa(g_pet_body, opa, 0);
    }

    /* remind 状态：闪烁效果 */
    if (g_state == PET_STATE_REMIND && g_pet_body)
    {
        lv_opa_t opa = (g_frame_idx % 2) ? LV_OPA_COVER : LV_OPA_50;
        lv_obj_set_style_bg_opa(g_pet_body, opa, 0);
    }

    /* 气泡倒计时隐藏 */
    if (g_bubble_cnt > 0)
    {
        g_bubble_cnt--;
        if (g_bubble_cnt == 0)
            pet_hide_bubble();
    }
}

/****************************************************************************
 * 空闲检测 timer（每秒检查一次）
 ****************************************************************************/

static void pet_idle_cb(lv_timer_t *t)
{
    (void)t;
    time_t now = time(NULL);
    int idle_s = (int)(now - g_pet_data.last_interaction);

    /* 5 分钟无互动 → sleeping */
    if (idle_s > PET_IDLE_TIMEOUT_S && g_state != PET_STATE_SLEEPING)
    {
        pet_set_state(PET_STATE_SLEEPING);
        LV_LOG_USER("[pet] idle %ds → sleeping", idle_s);
    }

    /* 心情衰减（每分钟 -1，最低 10） */
    static int decay_tick = 0;
    if (++decay_tick >= 60)
    {
        decay_tick = 0;
        if (g_pet_data.mood > PET_MOOD_MIN)
        {
            g_pet_data.mood -= PET_MOOD_DECAY_RATE;
            if (g_pet_data.mood < PET_MOOD_MIN)
                g_pet_data.mood = PET_MOOD_MIN;
        }
    }
}

/****************************************************************************
 * 自动保存 timer
 ****************************************************************************/

static void pet_save_cb(lv_timer_t *t)
{
    (void)t;
    pet_save();
}

/****************************************************************************
 * 事件处理（状态转移表）
 ****************************************************************************/

static void pet_process_event(dm_pet_event_t evt)
{
    g_pet_data.last_interaction = time(NULL);
    g_pet_data.growth++;

    /* 先从 sleeping 唤醒 */
    if (g_state == PET_STATE_SLEEPING &&
        evt != PET_EVT_IDLE_LONG)
    {
        pet_set_state(PET_STATE_IDLE);
    }

    switch (evt)
    {
    case PET_EVT_WATER_DRANK:
        g_pet_data.total_water++;
        g_pet_data.mood += 10;
        if (g_pet_data.mood > 100) g_pet_data.mood = 100;
        g_pet_data.energy += 5;
        if (g_pet_data.energy > 100) g_pet_data.energy = 100;
        pet_set_state(PET_STATE_HAPPY);
        break;

    case PET_EVT_STOOD_UP:
        g_pet_data.total_stands++;
        g_pet_data.mood += 5;
        if (g_pet_data.mood > 100) g_pet_data.mood = 100;
        g_pet_data.energy += 10;
        if (g_pet_data.energy > 100) g_pet_data.energy = 100;
        pet_set_state(PET_STATE_HAPPY);
        break;

    case PET_EVT_LONG_SIT:
        g_pet_data.mood -= 5;
        if (g_pet_data.mood < PET_MOOD_MIN)
            g_pet_data.mood = PET_MOOD_MIN;
        g_pet_data.energy -= 10;
        if (g_pet_data.energy < 0) g_pet_data.energy = 0;
        pet_set_state(PET_STATE_SAD);
        break;

    case PET_EVT_GOAL_REACHED:
        g_pet_data.mood = 100;
        pet_set_state(PET_STATE_CELEBRATE);
        break;

    case PET_EVT_REMIND:
        pet_set_state(PET_STATE_REMIND);
        break;

    case PET_EVT_TOUCH:
        g_pet_data.mood += 3;
        if (g_pet_data.mood > 100) g_pet_data.mood = 100;
        pet_set_state(PET_STATE_HAPPY);
        break;

    case PET_EVT_IDLE_LONG:
        pet_set_state(PET_STATE_SLEEPING);
        break;

    case PET_EVT_WAKE_UP:
        pet_set_state(PET_STATE_IDLE);
        break;

    default:
        break;
    }

    /* 显示气泡反应 */
    if (evt > PET_EVT_NONE && evt < PET_EVT_COUNT &&
        g_bubble_reactions[evt])
    {
        pet_show_bubble(g_bubble_reactions[evt]);
    }

    /* 立即保存关键事件 */
    if (evt == PET_EVT_WATER_DRANK || evt == PET_EVT_GOAL_REACHED)
        pet_save();
}

/****************************************************************************
 * 触摸回调（点击宠物）
 ****************************************************************************/

static void pet_click_cb(lv_event_t *e)
{
    (void)e;
    pet_process_event(PET_EVT_TOUCH);
}

/****************************************************************************
 * 对外 API
 ****************************************************************************/

int dm_pet_create(lv_obj_t *parent)
{
    if (!parent)
        return -1;

    /* 加载持久化数据 */
    pet_load();

    /* 容器：右下角定位 */
    g_pet_cont = lv_obj_create(parent);
    lv_obj_set_size(g_pet_cont, PET_SIZE + DM(80), PET_SIZE + DM(80));
    lv_obj_align(g_pet_cont, LV_ALIGN_BOTTOM_RIGHT,
                 -PET_MARGIN, -PET_MARGIN);
    lv_obj_set_style_bg_opa(g_pet_cont, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(g_pet_cont, 0, 0);
    lv_obj_set_style_pad_all(g_pet_cont, 0, 0);
    lv_obj_clear_flag(g_pet_cont, LV_OBJ_FLAG_SCROLLABLE);

    /* 身体：圆形 */
    g_pet_body = lv_obj_create(g_pet_cont);
    lv_obj_set_size(g_pet_body, PET_SIZE, PET_SIZE);
    lv_obj_align(g_pet_body, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_radius(g_pet_body, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_color(g_pet_body,
                              g_state_colors[PET_STATE_IDLE], 0);
    lv_obj_set_style_bg_opa(g_pet_body, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(g_pet_body, 0, 0);
    lv_obj_set_style_shadow_width(g_pet_body, 8, 0);
    lv_obj_set_style_shadow_color(g_pet_body,
                                  lv_color_hex(0x000000), 0);
    lv_obj_set_style_shadow_opa(g_pet_body, LV_OPA_30, 0);
    lv_obj_add_flag(g_pet_body, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(g_pet_body, pet_click_cb, LV_EVENT_CLICKED, NULL);

    /* 表情符号（居中） */
    g_pet_symbol = lv_label_create(g_pet_body);
    lv_label_set_text(g_pet_symbol, g_state_symbols[PET_STATE_IDLE]);
    lv_obj_set_style_text_font(g_pet_symbol, &lv_font_montserrat_48, 0);
    lv_obj_set_style_text_color(g_pet_symbol,
                                lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(g_pet_symbol);

    /* 气泡：宠物上方 */
    g_pet_bubble = lv_obj_create(g_pet_cont);
    lv_obj_set_size(g_pet_bubble, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_align(g_pet_bubble, LV_ALIGN_TOP_MID, 0, 0);
    lv_obj_set_style_bg_color(g_pet_bubble,
                              lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_bg_opa(g_pet_bubble, LV_OPA_90, 0);
    lv_obj_set_style_radius(g_pet_bubble, DM(10), 0);
    lv_obj_set_style_border_width(g_pet_bubble, 1, 0);
    lv_obj_set_style_border_color(g_pet_bubble,
                                  lv_color_hex(0xE0E0E0), 0);
    lv_obj_set_style_pad_hor(g_pet_bubble, DM(8), 0);
    lv_obj_set_style_pad_ver(g_pet_bubble, DM(4), 0);
    lv_obj_add_flag(g_pet_bubble, LV_OBJ_FLAG_HIDDEN);

    g_pet_bubble_lbl = lv_label_create(g_pet_bubble);
    lv_label_set_text(g_pet_bubble_lbl, "");
    lv_obj_set_style_text_font(g_pet_bubble_lbl,
                               &lv_font_montserrat_24, 0);
    lv_obj_set_style_text_color(g_pet_bubble_lbl,
                                lv_color_hex(0x333333), 0);

    /* 动画帧 timer */
    g_pet_anim_timer = lv_timer_create(pet_anim_cb, PET_FRAME_MS, NULL);

    /* 空闲检测 timer（1 秒周期） */
    g_pet_idle_timer = lv_timer_create(pet_idle_cb, 1000, NULL);

    /* 自动保存 timer */
    g_pet_save_timer = lv_timer_create(pet_save_cb,
                                       PET_SAVE_INTERVAL_S * 1000, NULL);

    /* 恢复上次状态 */
    if (g_pet_data.mood < 30)
        pet_set_state(PET_STATE_SAD);
    else
        pet_set_state(PET_STATE_IDLE);

    LV_LOG_USER("[pet] created: mood=%d energy=%d growth=%d",
                g_pet_data.mood, g_pet_data.energy, g_pet_data.growth);
    return 0;
}

void dm_pet_on_event(dm_pet_event_t evt)
{
    if (evt <= PET_EVT_NONE || evt >= PET_EVT_COUNT)
        return;

    /* 在 LVGL 主线程执行（事件可能来自 dm_health 后台线程） */
    lv_msg_send(evt, NULL);
}

/* LVGL 消息回调：在主线程中处理事件 */
static void pet_msg_cb(lv_event_t *e)
{
    dm_pet_event_t evt = (dm_pet_event_t)lv_event_get_code(e);
    pet_process_event(evt);
}

void dm_pet_deinit(void)
{
    pet_save();

    if (g_pet_anim_timer)
    {
        lv_timer_del(g_pet_anim_timer);
        g_pet_anim_timer = NULL;
    }
    if (g_pet_idle_timer)
    {
        lv_timer_del(g_pet_idle_timer);
        g_pet_idle_timer = NULL;
    }
    if (g_pet_save_timer)
    {
        lv_timer_del(g_pet_save_timer);
        g_pet_save_timer = NULL;
    }
    if (g_pet_cont)
    {
        lv_obj_del(g_pet_cont);
        g_pet_cont = NULL;
    }

    g_pet_body      = NULL;
    g_pet_symbol    = NULL;
    g_pet_bubble    = NULL;
    g_pet_bubble_lbl = NULL;

    LV_LOG_USER("[pet] deinit, state saved");
}

const dm_pet_data_t *dm_pet_get_data(void)
{
    return &g_pet_data;
}

/* 模块初始化时注册 LVGL 消息监听（在 dm_pet_create 之前调用一次） */
static void pet_msg_init(void)
{
    /* 注册消息回调：PET_EVT_* 作为消息 ID */
    for (int i = PET_EVT_NONE + 1; i < PET_EVT_COUNT; i++)
        lv_msg_subscribe(i, pet_msg_cb, NULL);
}

