/****************************************************************************
 * apps/vendor/allwinnertech/apps/pet_sim/pet_sim_main.c
 *
 * 2026-09-06：电子宠物模拟测试命令 pet_sim。
 * 调用 luncher_dm 的 dm_pet_on_event() 注入事件，
 * 不触发真实健康状态机即可验证宠物状态机+气泡+持久化。
 *
 * 用法（NSH）：
 *   pet_sim <event>         — 注入事件并打印结果
 *   pet_sim all             — 依次跑全部事件（间隔3s）
 *   pet_sim status          — 打印当前宠物数据
 *
 * event 名称：
 *   water=喝水  stand=起立  sit=久坐  goal=目标达成
 *   remind=提醒  touch=触摸  idle=长时间无互动  wake=唤醒
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/* dm_pet_event_t / dm_pet_data_t 定义在 luncher_dm/dm_pet.c，
 * 跨 app 符号共享（同 tone_test/voice_sim 先例）。
 * 头文件路径不含 luncher_dm 子目录——直接内联声明。 */

typedef enum
{
    PET_EVT_NONE = 0,
    PET_EVT_WATER_DRANK,
    PET_EVT_STOOD_UP,
    PET_EVT_LONG_SIT,
    PET_EVT_GOAL_REACHED,
    PET_EVT_REMIND,
    PET_EVT_TOUCH,
    PET_EVT_IDLE_LONG,
    PET_EVT_WAKE_UP,
    PET_EVT_COUNT
} dm_pet_event_t;

typedef struct
{
    int   mood;
    int   energy;
    int   growth;
    int   total_water;
    int   total_stands;
    int   days_alive;
    long  last_interaction;
} dm_pet_data_t;

extern void dm_pet_on_event(dm_pet_event_t evt);
extern const dm_pet_data_t *dm_pet_get_data(void);

typedef struct
{
    dm_pet_event_t evt;
    const char    *name;
    const char    *label;
} pet_event_info_t;

static const pet_event_info_t g_events[] =
{
    { PET_EVT_WATER_DRANK,  "water",  "喝水" },
    { PET_EVT_STOOD_UP,     "stand",  "起立" },
    { PET_EVT_LONG_SIT,     "sit",    "久坐超时" },
    { PET_EVT_GOAL_REACHED, "goal",   "目标达成" },
    { PET_EVT_REMIND,       "remind", "提醒" },
    { PET_EVT_TOUCH,        "touch",  "触摸" },
    { PET_EVT_IDLE_LONG,    "idle",   "长时间无互动" },
    { PET_EVT_WAKE_UP,      "wake",   "唤醒" },
};

#define EVT_COUNT (sizeof(g_events) / sizeof(g_events[0]))

static void print_status(void)
{
    const dm_pet_data_t *d = dm_pet_get_data();
    printf("[pet_sim] === 宠物状态 ===\n");
    printf("  mood=%d  energy=%d  growth=%d\n", d->mood, d->energy, d->growth);
    printf("  total_water=%d  total_stands=%d  days_alive=%d\n",
           d->total_water, d->total_stands, d->days_alive);
    printf("  last_interaction=%ld\n", d->last_interaction);
}

static void run_event(dm_pet_event_t evt, const char *name, const char *label)
{
    printf("[pet_sim] injecting: %s (%s)\n", name, label);
    dm_pet_on_event(evt);
    /* 给 LVGL 主线程一点时间处理消息 */
    usleep(200000);
    print_status();
}

int main(int argc, char *argv[])
{
    if (argc < 2)
    {
        printf("usage: pet_sim <event|all|status>\n");
        printf("  events: water stand sit goal remind touch idle wake\n");
        printf("  all     - run all events (3s gap)\n");
        printf("  status  - print current pet data\n");
        return 1;
    }

    if (strcmp(argv[1], "status") == 0)
    {
        print_status();
        return 0;
    }

    if (strcmp(argv[1], "all") == 0)
    {
        printf("[pet_sim] === 全事件遍历 ===\n");
        for (size_t i = 0; i < EVT_COUNT; i++)
        {
            run_event(g_events[i].evt, g_events[i].name, g_events[i].label);
            if (i + 1 < EVT_COUNT)
                sleep(3);
        }
        printf("[pet_sim] === done ===\n");
        return 0;
    }

    /* 查找事件 */
    for (size_t i = 0; i < EVT_COUNT; i++)
    {
        if (strcmp(argv[1], g_events[i].name) == 0)
        {
            run_event(g_events[i].evt, g_events[i].name, g_events[i].label);
            return 0;
        }
    }

    printf("pet_sim: unknown event '%s'\n", argv[1);
    printf("  valid: water stand sit goal remind touch idle wake\n");
    return 1;
}

