void dm_pet_on_event(dm_pet_event_t evt)
{
    if (evt <= PET_EVT_NONE || evt >= PET_EVT_COUNT)
        return;

    /* 线程安全入队（单生产者：dm_health 回调线程） */
    int next = (g_evt_head + 1) % PET_EVT_QUEUE_SIZE;
    if (next == g_evt_tail)
        return;  /* 队列满，丢弃 */
    g_evt_queue[g_evt_head] = evt;
    g_evt_head = next;
}

/* LVGL 主线程 timer：轮询事件队列，消费并处理 */
static void pet_poll_cb(lv_timer_t *t)
{
    (void)t;
    while (g_evt_tail != g_evt_head)
    {
        dm_pet_event_t evt = g_evt_queue[g_evt_tail];
        g_evt_tail = (g_evt_tail + 1) % PET_EVT_QUEUE_SIZE;
        pet_process_event(evt);
    }
}

void dm_pet_deinit(void)

