#ifndef __APPS_VENDOR_ALLWINNERTECH_APPS_LUNCHER_DM_DM_PET_H
#define __APPS_VENDOR_ALLWINNERTECH_APPS_LUNCHER_DM_DM_PET_H

#include <lvgl/lvgl.h>
#include <stdbool.h>

/****************************************************************************
 * 宠物类型
 ****************************************************************************/
typedef enum
{
    PET_TYPE_CAT = 0,       /* 猫：傲娇、慵懒、被动互动 */
    PET_TYPE_DOG,           /* 狗：热情、活泼、主动互动 */
    PET_TYPE_COUNT
} dm_pet_type_t;

/****************************************************************************
 * 宠物状态（行为系统的顶层分类）
 ****************************************************************************/
typedef enum
{
    PET_STATE_IDLE = 0,     /* 默认待机：随机行为池 */
    PET_STATE_WANDER,       /* 小范围移动 */
    PET_STATE_PLAY,         /* 玩耍中 */
    PET_STATE_EAT,          /* 吃东西中 */
    PET_STATE_SLEEP,        /* 睡觉 */
    PET_STATE_HAPPY,        /* 开心 */
    PET_STATE_SAD,          /* 不开心 */
    PET_STATE_HUNGRY,       /* 饥饿 */
    PET_STATE_CURIOUS,      /* 好奇 */
    PET_STATE_CELEBRATE,    /* 庆祝 */
    PET_STATE_COUNT
} dm_pet_state_t;

/****************************************************************************
 * 宠物事件（外部触发）
 ****************************************************************************/
typedef enum
{
    PET_EVT_NONE = 0,
    /* 健康联动 */
    PET_EVT_SIT_REMIND,     /* 久坐提醒触发 */
    PET_EVT_STOOD_UP,       /* 用户起立 */
    PET_EVT_WATER_DRANK,    /* 用户喝水 */
    PET_EVT_WATER_GOAL,     /* 喝水目标达成 */
    PET_EVT_HEALTH_GOAL,    /* 健康目标全部达成 */
    /* 触摸互动 */
    PET_EVT_TAP_BODY,       /* 轻点身体 */
    PET_EVT_TAP_HEAD,       /* 轻点头部 */
