static int clamp(int v, int lo, int hi)
{
    return v < lo ? lo : (v > hi ? hi : v);
}

static int rand_range(int lo, int hi)
{
    if (lo >= hi) return lo;
    return lo + rand() % (hi - lo + 1);
}

static const char *state_names[] =
{
    "IDLE", "WANDER", "PLAY", "EAT", "SLEEP",
