        return state_names[s];
    return "???";
}

dm_pet_life_stage_t dm_pet_get_life_stage(void)
{
    if (g_pet.attrs.growth < 100)  return PET_LIFE_BABY;
    if (g_pet.attrs.growth < 500)  return PET_LIFE_JUVENILE;
    return PET_LIFE_ADULT;
}

static int get_hour(void)
{
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    if (!utc) return -1;
    int h = utc->tm_hour + 8;
    if (h >= 24) h -= 24;
    return h;
}

/****************************************************************************
 * 持久化 — JSON 简易序列化/解析
 ****************************************************************************/

static void pet_save(void)
{
    FILE *f = fopen(PET_SAVE_PATH, "w");
    if (!f) return;
    fprintf(f,
        "{\"version\":%d,\"pet_type\":%d,\"name\":\"%s\","
        "\"hunger\":%d,\"energy\":%d,\"happiness\":%d,"
        "\"affection\":%d,\"health\":%d,\"growth\":%d,"
        "\"last_interaction\":%ld,\"last_update\":%ld,"
        "\"created_at\":%ld,\"total_days\":%d}\n",
        1, g_pet.pet_type, g_pet.name,
        g_pet.attrs.hunger, g_pet.attrs.energy, g_pet.attrs.happiness,
        g_pet.attrs.affection, g_pet.attrs.health, g_pet.attrs.growth,
        g_pet.last_interaction, g_pet.last_update,
        g_pet.created_at, g_pet.total_days);
    fclose(f);
}

static void pet_load(void)
{
    FILE *f = fopen(PET_SAVE_PATH, "r");
    if (!f)
    {
        /* 首次运行：默认猫 + "旺财" */
        memset(&g_pet, 0, sizeof(g_pet));
        g_pet.version   = 1;
        g_pet.pet_type  = PET_TYPE_CAT;
        strcpy(g_pet.name, "旺财");
        g_pet.attrs.hunger    = 50;
        g_pet.attrs.energy    = 80;
        g_pet.attrs.happiness = 60;
        g_pet.attrs.affection = 20;
        g_pet.attrs.health    = 100;
        g_pet.attrs.growth    = 0;
        g_pet.last_interaction = time(NULL);
        g_pet.last_update      = time(NULL);
        g_pet.created_at       = time(NULL);
        g_pet.total_days       = 0;
        LV_LOG_USER("[pet] first boot: %s the cat", g_pet.name);
        return;
    }
    /* 解析 */
    fscanf(f,
        "{\"version\":%d,\"pet_type\":%d,\"name\":\"%31[^\"]\","
        "\"hunger\":%d,\"energy\":%d,\"happiness\":%d,"
        "\"affection\":%d,\"health\":%d,\"growth\":%d,"
        "\"last_interaction\":%ld,\"last_update\":%ld,"
        "\"created_at\":%ld,\"total_days\":%d",
        &g_pet.version, (int *)&g_pet.pet_type, g_pet.name,
        &g_pet.attrs.hunger, &g_pet.attrs.energy, &g_pet.attrs.happiness,
        &g_pet.attrs.affection, &g_pet.attrs.health, &g_pet.attrs.growth,
        &g_pet.last_interaction, &g_pet.last_update,
        &g_pet.created_at, &g_pet.total_days);
    fclose(f);

    /* 离线时间计算：关机期间属性缓慢变化 */
    time_t now = time(NULL);
    long elapsed_h = (now - g_pet.last_update) / 3600;
    if (elapsed_h > 0 && elapsed_h < 720)  /* 最多算30天 */
    {
        int hunger_rate = (g_pet.pet_type == PET_TYPE_DOG) ? 2 : 1;
        g_pet.attrs.hunger    = clamp(g_pet.attrs.hunger + hunger_rate * elapsed_h, 0, 100);
        g_pet.attrs.energy    = clamp(g_pet.attrs.energy + elapsed_h / 2, 0, 100); /* 离线恢复精力 */
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness - elapsed_h / 10, PET_HAPPINESS_FLOOR, 100);
        if (g_pet.attrs.hunger < 20)
            g_pet.attrs.health = clamp(g_pet.attrs.health - elapsed_h, PET_HEALTH_FLOOR, 100);
        g_pet.total_days += elapsed_h / 24;
    }
    g_pet.last_update = now;

    LV_LOG_USER("[pet] loaded: %s type=%d hunger=%d happy=%d growth=%d",
                g_pet.name, g_pet.pet_type, g_pet.attrs.hunger,
                g_pet.attrs.happiness, g_pet.attrs.growth);
}

/****************************************************************************
 * 属性系统
 ****************************************************************************/

static void pet_update_attrs_tick(void)
{
    /* 每分钟调用一次（由 PET_EVT_TIME_TICK 驱动） */
    int hunger_rate = (g_pet.pet_type == PET_TYPE_DOG) ? 2 : 1;

    /* 饥饿增长 */
    g_pet.attrs.hunger = clamp(g_pet.attrs.hunger + hunger_rate, 0, 100);

    /* 精力衰减（醒时） */
    if (g_state != PET_STATE_SLEEP)
        g_pet.attrs.energy = clamp(g_pet.attrs.energy - 1, 0, 100);

    /* 快乐衰减 */
    g_pet.attrs.happiness = clamp(g_pet.attrs.happiness - 1, 0, 100);

    /* 健康间接衰减 */
    if (g_pet.attrs.hunger < 20)
        g_pet.attrs.health = clamp(g_pet.attrs.health - 1, PET_HEALTH_FLOOR, 100);

    /* 精力恢复（睡觉时） */
    if (g_state == PET_STATE_SLEEP)
        g_pet.attrs.energy = clamp(g_pet.attrs.energy + 3, 0, 100);

    g_pet.last_update = time(NULL);
}

/****************************************************************************
 * 状态转移逻辑
 ****************************************************************************/

static dm_pet_state_t pet_next_state(void)
{
    int h = get_hour();

    /* 深夜强制睡觉 */
    if (h >= 0 && h < 6 && g_state != PET_STATE_SLEEP)
        return PET_STATE_SLEEP;

    /* 精力耗尽 */
    if (g_pet.attrs.energy < 10 && g_state != PET_STATE_SLEEP)
        return PET_STATE_SLEEP;

    /* 饥饿 */
    if (g_pet.attrs.hunger > 80 && g_state != PET_STATE_EAT &&
        g_state != PET_STATE_SLEEP)
        return PET_STATE_HUNGRY;

    /* 快乐极低 */
    if (g_pet.attrs.happiness < 20 && g_state != PET_STATE_SLEEP &&
        g_state != PET_STATE_SAD)
        return PET_STATE_SAD;

    return PET_STATE_IDLE;
}

static void pet_apply_state_effects(void)
{
    /* 状态切换时的属性微调 */
    switch (g_state)
    {
    case PET_STATE_SLEEP:
        /* 睡觉恢复精力 */
        g_pet.attrs.energy = clamp(g_pet.attrs.energy + 5, 0, 100);
        break;
    case PET_STATE_HAPPY:
    case PET_STATE_CELEBRATE:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 2, 0, 100);
        break;
    case PET_STATE_SAD:
        /* 不额外惩罚，只是表现 */
        break;
    default:
        break;
    }
}

/****************************************************************************
 * 行为选择（加权随机）
 ****************************************************************************/

static const pet_behavior_t *pick_from_pool(const pet_behavior_t *pool,
                                            int count)
{
    int total = 0;
    for (int i = 0; i < count; i++)
        total += pool[i].weight;
    if (total <= 0) return &pool[0];

    int r = rand() % total;
    for (int i = 0; i < count; i++)
    {
        r -= pool[i].weight;
        if (r < 0) return &pool[i];
    }
    return &pool[count - 1];
}

static void pet_select_behavior(void)
{
    const pet_behavior_t *b = NULL;

    switch (g_state)
    {
    case PET_STATE_IDLE:
    case PET_STATE_WANDER:
        if (g_pet.pet_type == PET_TYPE_CAT)
            b = pick_from_pool(g_cat_idle, CAT_IDLE_COUNT);
        else
            b = pick_from_pool(g_dog_idle, DOG_IDLE_COUNT);
        break;
    case PET_STATE_SLEEP:
        b = pick_from_pool(g_sleep_behaviors, SLEEP_COUNT);
        break;
    case PET_STATE_HAPPY:
        b = pick_from_pool(g_happy_behaviors, HAPPY_COUNT);
        break;
    case PET_STATE_SAD:
        b = pick_from_pool(g_sad_behaviors, SAD_COUNT);
        break;
    case PET_STATE_CELEBRATE:
        b = pick_from_pool(g_celebrate_behaviors, CELEBRATE_COUNT);
        break;
    default:
        /* EAT/PLAY/HUNGRY/CURIOUS 由事件直接驱动，不走随机 */
        break;
    }

    if (b)
    {
        g_cur_behavior = b;
        g_behavior_ticks_left = b->duration;

        /* 更新占位精灵 */
        if (g_body)
            lv_obj_set_style_bg_color(g_body, g_state_colors[g_state], 0);
        if (g_symbol)
            lv_label_set_text(g_symbol, b->symbol);
        if (b->bubble && g_bubble && g_bubble_lbl)
        {
            lv_label_set_text(g_bubble_lbl, b->bubble);
            lv_obj_clear_flag(g_bubble, LV_OBJ_FLAG_HIDDEN);
            g_bubble_ticks = PET_BUBBLE_DURATION_TICKS;
        }
    }
}

/****************************************************************************
 * 事件处理
 ****************************************************************************/

static void pet_process_event(dm_pet_event_t evt, int param)
{
    (void)param;
    dm_pet_state_t old_state = g_state;

    /* 健康联动事件 */
    switch (evt)
    {
    case PET_EVT_WATER_DRANK:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 3, 0, 100);
        g_pet.attrs.affection = clamp(g_pet.attrs.affection + 1, 0, 100);
        g_pet.attrs.growth++;
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_HAPPY;
        break;

    case PET_EVT_STOOD_UP:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 2, 0, 100);
        g_pet.attrs.affection = clamp(g_pet.attrs.affection + 1, 0, 100);
        g_pet.attrs.growth++;
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_HAPPY;
        break;

    case PET_EVT_SIT_REMIND:
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_CURIOUS;
        break;

    case PET_EVT_WATER_GOAL:
    case PET_EVT_HEALTH_GOAL:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 10, 0, 100);
        g_pet.attrs.growth += 5;
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_CELEBRATE;
        break;

    /* 触摸互动 */
    case PET_EVT_TAP_HEAD:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 2, 0, 100);
        g_pet.attrs.affection = clamp(g_pet.attrs.affection + 1, 0, 100);
        g_pet.last_interaction = time(NULL);
        if (g_pet.pet_type == PET_TYPE_CAT)
            g_state = PET_STATE_HAPPY;  /* 猫被摸头开心 */
        else
            g_state = PET_STATE_HAPPY;  /* 狗更开心 */
        break;

    case PET_EVT_TAP_BODY:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 1, 0, 100);
        g_pet.last_interaction = time(NULL);
        /* 猫可能不理你，狗一定回应 */
        if (g_pet.pet_type == PET_TYPE_DOG || (rand() % 3) > 0)
            g_state = PET_STATE_HAPPY;
        break;

    case PET_EVT_LONG_PRESS:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 3, 0, 100);
        g_pet.attrs.affection = clamp(g_pet.attrs.affection + 2, 0, 100);
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_HAPPY;
        break;

    case PET_EVT_RAPID_TAP:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 5, 0, 100);
        g_pet.attrs.energy = clamp(g_pet.attrs.energy - 5, 0, 100);
        g_pet.attrs.growth += 2;
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_PLAY;
        break;

    case PET_EVT_DRAG:
        g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + 2, 0, 100);
        g_pet.last_interaction = time(NULL);
        g_state = PET_STATE_PLAY;
        break;

    /* 投喂 */
    case PET_EVT_FEED_FISH:
    case PET_EVT_FEED_MEAT:
    case PET_EVT_FEED_VEGGIE:
    case PET_EVT_FEED_SNACK:
    {
        int fi = evt - PET_EVT_FEED_FISH;
        if (fi >= 0 && fi < PET_FOOD_COUNT)
        {
            const pet_food_effect_t *fe = &g_food_effects[fi];
            g_pet.attrs.hunger    = clamp(g_pet.attrs.hunger + fe->hunger_delta, 0, 100);
            g_pet.attrs.happiness = clamp(g_pet.attrs.happiness + fe->happiness_delta, 0, 100);
            g_pet.attrs.affection = clamp(g_pet.attrs.affection + fe->affection_delta, 0, 100);
            g_pet.attrs.growth++;
            g_pet.last_interaction = time(NULL);
            g_state = PET_STATE_EAT;
        }
        break;
    }

    /* 环境 */
    case PET_EVT_MUSIC_ON:
        g_state = PET_STATE_CURIOUS;
        break;

    case PET_EVT_WAKE_UP:
        /* 暂停动画 */
        if (g_anim_timer) lv_timer_pause(g_anim_timer);
        if (g_behavior_timer) lv_timer_pause(g_behavior_timer);
        break;

    case PET_EVT_SLEEP:
        /* 恢复动画 */
        if (g_anim_timer) lv_timer_resume(g_anim_timer);
        if (g_behavior_timer) lv_timer_resume(g_behavior_timer);
        break;

    case PET_EVT_TIME_TICK:
        pet_update_attrs_tick();
        /* 检查是否需要状态转移 */
        {
            dm_pet_state_t next = pet_next_state();
            if (next != g_state)
                g_state = next;
        }
        break;

    default:
        break;
    }

    /* 状态切换后选新行为 */
    if (g_state != old_state)
    {
        pet_apply_state_effects();
        pet_select_behavior();
        LV_LOG_USER("[pet] %s → %s (evt=%d)",
                    dm_pet_state_name(old_state),
                    dm_pet_state_name(g_state), evt);
    }

    /* 关键事件立即保存 */
    if (evt == PET_EVT_FEED_FISH || evt == PET_EVT_FEED_MEAT ||
        evt == PET_EVT_FEED_VEGGIE || evt == PET_EVT_FEED_SNACK ||
        evt == PET_EVT_WATER_GOAL || evt == PET_EVT_HEALTH_GOAL)
    {
        pet_save();
    }
}

/****************************************************************************
 * LVGL 事件队列轮询
 ****************************************************************************/

static void pet_poll_cb(lv_timer_t *t)
{
    (void)t;
    while (g_evt_tail != g_evt_head)
    {
        pet_evt_entry_t e = g_evt_queue[g_evt_tail];
        g_evt_tail = (g_evt_tail + 1) % EVT_QUEUE_SIZE;
        pet_process_event(e.evt, e.param);
    }
}

/****************************************************************************
 * 行为 timer（每 PET_BEHAVIOR_TICK_MS）
 ****************************************************************************/

static void pet_behavior_cb(lv_timer_t *t)
{
    (void)t;
    g_tick++;

    /* 行为倒计时 */
    if (g_behavior_ticks_left > 0)
    {
        g_behavior_ticks_left--;
        if (g_behavior_ticks_left == 0)
            pet_select_behavior();
    }
    else
    {
        pet_select_behavior();
    }

    /* 气泡倒计时 */
    if (g_bubble_ticks > 0)
    {
        g_bubble_ticks--;
        if (g_bubble_ticks == 0 && g_bubble)
            lv_obj_add_flag(g_bubble, LV_OBJ_FLAG_HIDDEN);
    }
}

/****************************************************************************
 * 动画帧 timer（每 PET_ANIM_TICK_MS）
 ****************************************************************************/

static void pet_anim_cb(lv_timer_t *t)
{
    (void)t;
    if (!g_cur_behavior || !g_body) return;

    /* 占位动画：根据行为做简单效果 */
    if (g_state == PET_STATE_SLEEP)
    {
        /* 呼吸效果 */
        lv_opa_t opa = (lv_opa_t)(180 + 75 * ((g_tick % 4 < 2) ? 1 : -1));
        lv_obj_set_style_bg_opa(g_body, opa, 0);
    }
    else if (g_state == PET_STATE_PLAY)
    {
        /* 跳动效果 */
        int off = (g_tick % 2) ? -8 : 8;
        lv_obj_set_y(g_cont, lv_obj_get_y(g_cont) + off);
    }
    else if (g_state == PET_STATE_CELEBRATE)
    {
        /* 快速跳动 */
        int off = (g_tick % 2) ? -12 : 12;
        lv_obj_set_y(g_cont, lv_obj_get_y(g_cont) + off);
    }
    else if (g_state == PET_STATE_HUNGRY)
    {
        /* 闪烁 */
        lv_opa_t opa = (g_tick % 2) ? LV_OPA_COVER : LV_OPA_50;
        lv_obj_set_style_bg_opa(g_body, opa, 0);
    }
    else if (g_state == PET_STATE_IDLE || g_state == PET_STATE_WANDER)
    {
        /* 轻微浮动 */
        static const int offsets[] = {0, -2, 0, 2, 0};
        int off = offsets[g_tick % 5];
        if (off != 0)
            lv_obj_set_y(g_cont, lv_obj_get_y(g_cont) + off);
    }
}

/****************************************************************************
 * 保存 timer
 ****************************************************************************/

static void pet_save_cb(lv_timer_t *t)
{
    (void)t;
    pet_save();
}

/****************************************************************************
 * 触摸回调
 ****************************************************************************/

static void pet_body_press_cb(lv_event_t *e)
{
    (void)e;
    g_press_active = true;
    g_press_start_ms = lv_tick_get();
}

static void pet_body_release_cb(lv_event_t *e)
{
    (void)e;
    if (!g_press_active) return;
    g_press_active = false;

    uint32_t duration = lv_tick_get() - g_press_start_ms;
    uint32_t now = lv_tick_get();

    if (duration >= PET_LONG_PRESS_MS)
    {
        /* 长按 = 抚摸 */
        dm_pet_on_event(PET_EVT_LONG_PRESS);
    }
    else
    {
        /* 短按 = 轻点 */
        uint32_t gap = now - g_last_tap_ms;
        g_last_tap_ms = now;

        if (gap < PET_RAPID_TAP_WINDOW_MS)
            g_rapid_tap_count++;
        else
            g_rapid_tap_count = 1;

        if (g_rapid_tap_count >= PET_RAPID_TAP_COUNT)
        {
            dm_pet_on_event(PET_EVT_RAPID_TAP);
            g_rapid_tap_count = 0;
        }
        else
        {
            /* 判断触摸区域（简单：上1/3 = 头部） */
            lv_coord_t y = lv_obj_get_y(g_body);
            lv_coord_t h = lv_obj_get_height(g_body);
            lv_indev_t *indev = lv_indev_get_act();
            lv_point_t pt;
            if (indev)
            {
                lv_indev_get_point(indev, &pt);
                if (pt.y < y + h / 3)
                    dm_pet_on_event(PET_EVT_TAP_HEAD);
                else
                    dm_pet_on_event(PET_EVT_TAP_BODY);
            }
            else
            {
                dm_pet_on_event(PET_EVT_TAP_BODY);
            }
        }
    }
}

/****************************************************************************
 * 对外 API
 ****************************************************************************/

int dm_pet_create(lv_obj_t *parent)
{
    if (!parent) return -1;

    if (!g_inited)
    {
        srand((unsigned)time(NULL));
        pet_load();
        g_inited = true;
    }

    /* 容器：右下角 */
    g_cont = lv_obj_create(parent);
    lv_obj_set_size(g_cont, PET_SIZE + DM(60), PET_SIZE + DM(80));
    lv_obj_align(g_cont, LV_ALIGN_BOTTOM_RIGHT, -DM(20), -DM(20));
    lv_obj_set_style_bg_opa(g_cont, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(g_cont, 0, 0);
    lv_obj_set_style_pad_all(g_cont, 0, 0);
    lv_obj_clear_flag(g_cont, LV_OBJ_FLAG_SCROLLABLE);

    /* 身体（圆形占位） */
    g_body = lv_obj_create(g_cont);
    lv_obj_set_size(g_body, PET_SIZE, PET_SIZE);
    lv_obj_align(g_body, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_radius(g_body, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_color(g_body, g_state_colors[g_state], 0);
    lv_obj_set_style_bg_opa(g_body, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(g_body, 0, 0);
    lv_obj_set_style_shadow_width(g_body, 8, 0);
    lv_obj_set_style_shadow_opa(g_body, LV_OPA_30, 0);
    lv_obj_add_flag(g_body, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(g_body, pet_body_press_cb, LV_EVENT_PRESSED, NULL);
    lv_obj_add_event_cb(g_body, pet_body_release_cb, LV_EVENT_RELEASED, NULL);

    /* 表情符号 */
    g_symbol = lv_label_create(g_body);
    lv_label_set_text(g_symbol, LV_SYMBOL_EYE_OPEN);
    lv_obj_set_style_text_font(g_symbol, PET_SYMBOL_FONT, 0);
    lv_obj_set_style_text_color(g_symbol, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(g_symbol);

    /* 气泡 */
    g_bubble = lv_obj_create(g_cont);
    lv_obj_set_size(g_bubble, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_align(g_bubble, LV_ALIGN_TOP_MID, 0, 0);
    lv_obj_set_style_bg_color(g_bubble, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_bg_opa(g_bubble, LV_OPA_90, 0);
    lv_obj_set_style_radius(g_bubble, DM(10), 0);
    lv_obj_set_style_border_width(g_bubble, 1, 0);
    lv_obj_set_style_border_color(g_bubble, lv_color_hex(0xE0E0E0), 0);
    lv_obj_set_style_pad_hor(g_bubble, DM(8), 0);
    lv_obj_set_style_pad_ver(g_bubble, DM(4), 0);
    lv_obj_add_flag(g_bubble, LV_OBJ_FLAG_HIDDEN);

    g_bubble_lbl = lv_label_create(g_bubble);
    lv_label_set_text(g_bubble_lbl, "");
    lv_obj_set_style_text_font(g_bubble_lbl, PET_BUBBLE_FONT, 0);
    lv_obj_set_style_text_color(g_bubble_lbl, lv_color_hex(0x333333), 0);

    /* Timer 创建 */
    g_anim_timer     = lv_timer_create(pet_anim_cb, PET_ANIM_TICK_MS, NULL);
    g_behavior_timer = lv_timer_create(pet_behavior_cb, PET_BEHAVIOR_TICK_MS, NULL);
    g_save_timer     = lv_timer_create(pet_save_cb, PET_SAVE_INTERVAL_S * 1000, NULL);
    g_poll_timer     = lv_timer_create(pet_poll_cb, 100, NULL);

    /* 初始行为 */
    g_state = pet_next_state();
    pet_select_behavior();

    LV_LOG_USER("[pet] created: %s (type=%d) state=%s mood=%d/%d/%d",
                g_pet.name, g_pet.pet_type, dm_pet_state_name(g_state),
                g_pet.attrs.hunger, g_pet.attrs.happiness, g_pet.attrs.energy);
    return 0;
}

void dm_pet_on_event(dm_pet_event_t evt)
{
    dm_pet_on_event_param(evt, 0);
}

void dm_pet_on_event_param(dm_pet_event_t evt, int param)
{
    if (evt <= PET_EVT_NONE || evt >= PET_EVT_COUNT) return;
    int next = (g_evt_head + 1) % EVT_QUEUE_SIZE;
    if (next == g_evt_tail) return;
    g_evt_queue[g_evt_head] = (pet_evt_entry_t){evt, param};
    g_evt_head = next;
}

void dm_pet_deinit(void)
{
    pet_save();
    if (g_anim_timer)     { lv_timer_del(g_anim_timer);     g_anim_timer = NULL; }
    if (g_behavior_timer) { lv_timer_del(g_behavior_timer); g_behavior_timer = NULL; }
    if (g_save_timer)     { lv_timer_del(g_save_timer);     g_save_timer = NULL; }
    if (g_poll_timer)     { lv_timer_del(g_poll_timer);     g_poll_timer = NULL; }
    if (g_cont)           { lv_obj_del(g_cont);             g_cont = NULL; }
    g_body = NULL; g_symbol = NULL; g_bubble = NULL; g_bubble_lbl = NULL;
    LV_LOG_USER("[pet] deinit, state saved");
}

const dm_pet_data_t *dm_pet_get_data(void)
{
    return &g_pet;
}

/****************************************************************************
 * apps/vendor/allwinnertech/apps/pet_sim/pet_sim_main.c
 *
 * 电子宠物模拟测试命令 pet_sim。
 * 调用 luncher_dm 的 dm_pet_on_event() / dm_pet_on_event_param()，
 * 不触发真实健康状态机即可验证宠物状态机+属性+行为+持久化。
 *
 * 用法（NSH）：
 *   pet_sim <event>         — 注入事件并打印结果
 *   pet_sim all             — 依次跑全部核心事件（间隔3s）
 *   pet_sim status          — 打印当前宠物数据
 *   pet_sim feed <food>     — 投喂（fish/meat/veggie/snack）
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/* 内联声明（不 include dm_pet.h，同 tone_test/voice_sim 先例） */

typedef enum
{
    PET_TYPE_CAT = 0, PET_TYPE_DOG, PET_TYPE_COUNT
} dm_pet_type_t;

typedef enum
{
    PET_STATE_IDLE = 0, PET_STATE_WANDER, PET_STATE_PLAY, PET_STATE_EAT,
    PET_STATE_SLEEP, PET_STATE_HAPPY, PET_STATE_SAD, PET_STATE_HUNGRY,
    PET_STATE_CURIOUS, PET_STATE_CELEBRATE, PET_STATE_COUNT
} dm_pet_state_t;

typedef enum
{
    PET_EVT_NONE = 0,
    PET_EVT_SIT_REMIND, PET_EVT_STOOD_UP, PET_EVT_WATER_DRANK,
    PET_EVT_WATER_GOAL, PET_EVT_HEALTH_GOAL,
    PET_EVT_TAP_BODY, PET_EVT_TAP_HEAD, PET_EVT_LONG_PRESS,
    PET_EVT_RAPID_TAP, PET_EVT_DRAG,
    PET_EVT_FEED_FISH, PET_EVT_FEED_MEAT, PET_EVT_FEED_VEGGIE,
    PET_EVT_FEED_SNACK,
    PET_EVT_MUSIC_ON, PET_EVT_MUSIC_OFF, PET_EVT_WEATHER_CHANGE,
    PET_EVT_VOICE_CMD,
    PET_EVT_WAKE_UP, PET_EVT_SLEEP, PET_EVT_TIME_TICK,
    PET_EVT_COUNT
} dm_pet_event_t;

typedef struct
{
    int hunger; int energy; int happiness;
    int affection; int health; int growth;
} dm_pet_attrs_t;

typedef struct
{
    int version; dm_pet_type_t pet_type; char name[32];
    dm_pet_attrs_t attrs;
    long last_interaction; long last_update; long created_at; int total_days;
} dm_pet_data_t;

extern void dm_pet_on_event(dm_pet_event_t evt);
extern void dm_pet_on_event_param(dm_pet_event_t evt, int param);
extern const dm_pet_data_t *dm_pet_get_data(void);
extern const char *dm_pet_state_name(dm_pet_state_t state);

typedef struct { dm_pet_event_t evt; const char *name; const char *label; } evt_info_t;

static const evt_info_t g_events[] =
{
    {PET_EVT_SIT_REMIND,  "sit",     "久坐提醒"},
    {PET_EVT_STOOD_UP,     "stand",   "起立"},
    {PET_EVT_WATER_DRANK,  "water",   "喝水"},
    {PET_EVT_WATER_GOAL,   "wgoal",   "喝水目标"},
    {PET_EVT_HEALTH_GOAL,  "hgoal",   "健康目标"},
    {PET_EVT_TAP_BODY,     "tap",     "点身体"},
