    {PET_EVT_RAPID_TAP,    "play",    "快速点击"},
    {PET_EVT_DRAG,         "drag",    "拖拽"},
    {PET_EVT_FEED_FISH,    "fish",    "喂鱼"},
    {PET_EVT_FEED_MEAT,    "meat",    "喂肉"},
    {PET_EVT_FEED_VEGGIE,  "veggie",  "喂蔬菜"},
    {PET_EVT_FEED_SNACK,   "snack",   "喂零食"},
    {PET_EVT_MUSIC_ON,     "music",   "音乐播放"},
    {PET_EVT_WAKE_UP,      "wake",    "唤醒"},
    {PET_EVT_SLEEP,        "sleep",   "进入锁屏"},
    {PET_EVT_TIME_TICK,    "tick",    "时间推进"},
};
#define EVT_COUNT (sizeof(g_events) / sizeof(g_events[0]))

static void print_status(void)
{
    const dm_pet_data_t *d = dm_pet_get_data();
    printf("[pet_sim] === %s (type=%d) ===\n", d->name, d->pet_type);
    printf("  hunger=%d  energy=%d  happiness=%d\n",
           d->attrs.hunger, d->attrs.energy, d->attrs.happiness);
    printf("  affection=%d  health=%d  growth=%d\n",
           d->attrs.affection, d->attrs.health, d->attrs.growth);
    printf("  days=%d\n", d->total_days);
}

int main(int argc, char *argv[])
{
    if (argc < 2)
    {
        printf("usage: pet_sim <event|all|status|feed>\n");
        printf("  events: sit stand water wgoal hgoal tap head pet play\n");
        printf("          drag fish meat veggie snack music wake sleep tick\n");
        printf("  all     - run core events (3s gap)\n");
        printf("  status  - print pet data\n");
        printf("  feed <food> - feed (fish/meat/veggie/snack)\n");
        return 1;
    }

    if (strcmp(argv[1], "status") == 0)
    {
        print_status();
        return 0;
    }

    if (strcmp(argv[1], "all") == 0)
    {
        printf("[pet_sim] === core events ===\n");
        dm_pet_on_event(PET_EVT_WATER_DRANK);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_STOOD_UP);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_TAP_HEAD);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_FEED_FISH);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_LONG_PRESS);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_RAPID_TAP);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_SIT_REMIND);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_HEALTH_GOAL);
        usleep(300000); print_status();
        dm_pet_on_event(PET_EVT_TIME_TICK);
        usleep(300000); print_status();
        printf("[pet_sim] === done ===\n");
        return 0;
    }

    if (strcmp(argv[1], "feed") == 0)
    {
        if (argc < 3)
        {
            printf("usage: pet_sim feed <fish|meat|veggie|snack>\n");
            return 1;
        }
        const char *foods[] = {"fish", "meat", "veggie", "snack"};
        dm_pet_event_t evts[] = {PET_EVT_FEED_FISH, PET_EVT_FEED_MEAT,
                                 PET_EVT_FEED_VEGGIE, PET_EVT_FEED_SNACK};
        for (int i = 0; i < 4; i++)
        {
            if (strcmp(argv[2], foods[i]) == 0)
            {
                printf("[pet_sim] feeding: %s\n", foods[i]);
                dm_pet_on_event(evts[i]);
                usleep(200000);
                print_status();
                return 0;
            }
        }
        printf("pet_sim: unknown food '%s' (fish/meat/veggie/snack)\n", argv[2]);
        return 1;
    }

    /* 查找事件 */
    for (size_t i = 0; i < EVT_COUNT; i++)
    {
        if (strcmp(argv[1], g_events[i].name) == 0)
        {
            printf("[pet_sim] injecting: %s (%s)\n",
                   g_events[i].name, g_events[i].label);
            dm_pet_on_event(g_events[i].evt);
            usleep(200000);
            print_status();
            return 0;
        }
    }

    printf("pet_sim: unknown event '%s'\n", argv[1]);
    return 1;
}

